import html
import json

from pydantic import BaseModel, Field

from .completed_exam import MockExamFileInput as MockExamFileInput

from .models import (
    OfflineFlashcard,
    OfflineFormula,
    PackageModel,
    PackageValidationReport,
)


class FlashcardFileInput(PackageModel):
    package_id: str = Field(min_length=1)
    file_id: str = Field(min_length=1)
    version: int = Field(ge=1)
    title: str = Field(min_length=1)
    cards: tuple[OfflineFlashcard, ...] = Field(min_length=1)


class FormulaFileInput(PackageModel):
    package_id: str = Field(min_length=1)
    file_id: str = Field(min_length=1)
    version: int = Field(ge=1)
    title: str = Field(min_length=1)
    formulas: tuple[OfflineFormula, ...] = Field(min_length=1)


class BlueprintFileInput(PackageModel):
    package_id: str = Field(min_length=1)
    file_id: str = Field(min_length=1)
    version: int = Field(ge=1)
    title: str = Field(min_length=1)
    domain_weights: dict[str, int]
    exam_domain_counts: tuple[dict[str, int], ...]
    question_type_counts: dict[str, int]
    difficulty_counts: tuple[dict[str, int], ...]


class ValidationFileInput(PackageModel):
    package_id: str = Field(min_length=1)
    file_id: str = Field(min_length=1)
    version: int = Field(ge=1)
    title: str = Field(min_length=1)
    report: PackageValidationReport


class OfflineRenderer:
    def render_flashcards(self, deck: FlashcardFileInput) -> str:
        body = """
<header><div><p class="eyebrow">Offline flashcards</p><h1 id="title"></h1></div><div class="progress"><strong id="position"></strong><span id="mastery"></span></div></header>
<section class="toolbar" aria-label="Card filters"><label>Search cards<input id="search" type="search" autocomplete="off"></label><label>Card type<select id="type-filter"><option value="">All types</option></select></label><label>Difficulty<select id="difficulty-filter"><option value="">All levels</option></select></label><button data-action="shuffle" type="button">Shuffle</button><button data-action="fullscreen" type="button">Fullscreen</button></section>
<main class="flashcard-workspace"><aside class="deck-browser" aria-label="Browse study cards"><div class="browser-heading"><div><p class="eyebrow">Learning objectives</p><strong id="objective-count"></strong></div><div class="compact-actions"><button data-action="select-all-objectives" type="button">Select all</button><button data-action="clear-objectives" type="button">Clear</button></div></div><div id="objective-options" class="objective-options"></div><div class="browser-heading card-list-heading"><div><p class="eyebrow">Cards in view</p><strong id="visible-card-count"></strong></div></div><nav id="card-list" class="card-list" aria-label="Jump to a card"><button aria-current="true" type="button">Loading cards...</button></nav></aside><section class="deck-column"><div class="deck-stage"><button class="side-nav" data-action="previous" type="button" aria-label="Previous card">&#8592;</button><article id="card" class="study-card" tabindex="0"><p class="eyebrow" id="concept"></p><h2 id="prompt"></h2><section id="answer" hidden><div class="rule"></div><p id="answer-text"></p><details><summary>Book reference</summary><p id="source"></p></details></section><button data-action="flip" class="flip" type="button">Show answer</button></article><button class="side-nav" data-action="next" type="button" aria-label="Next card">&#8594;</button></div><section class="ratings" aria-label="Rate recall"><button data-rating="again" type="button">Again</button><button data-rating="hard" type="button">Hard</button><button data-rating="good" type="button">Good</button><button data-rating="easy" type="button">Easy</button></section></section></main>
<footer><button data-action="export" type="button">Export progress</button><button id="import-progress-button" data-action="import" type="button">Import progress</button><input id="import-progress" type="file" accept="application/json" hidden><button data-action="reset" type="button">Reset</button></footer>
"""
        script = """
const payload=JSON.parse(document.getElementById("study-data").textContent);const storageKey=`exam-prep:${payload.package_id}:${payload.file_id}:v${payload.version}`;
const saved=JSON.parse(localStorage.getItem(storageKey)||"null");const legacyObjective=saved?.learningObjective||"";let state={index:0,revealed:false,ratings:{},shuffle:[],query:"",selectedObjectives:[],cardType:"",difficulty:"",...(saved||{})};delete state.learningObjective;
const byId=id=>document.getElementById(id);const save=()=>localStorage.setItem(storageKey,JSON.stringify(state));
const addOptions=(id,values)=>[...new Set(values)].sort().forEach(value=>{const option=document.createElement("option");option.value=value;option.textContent=value.replaceAll("_"," ");byId(id).append(option)});
const populate=()=>{byId("title").textContent=payload.title;addOptions("type-filter",payload.cards.map(card=>card.card_type));addOptions("difficulty-filter",payload.cards.map(card=>card.difficulty));byId("search").value=state.query;byId("type-filter").value=state.cardType;byId("difficulty-filter").value=state.difficulty};
const objectiveLabel=card=>{const code=card.learning_objective.trim();const title=(card.learning_objective_title||"").trim();return title&&title.toLocaleLowerCase()!==code.toLocaleLowerCase()?`${code} - ${title}`:code};
const objectives=()=>{const grouped=new Map();payload.cards.forEach(card=>{const key=card.learning_objective;const current=grouped.get(key)||{key,label:objectiveLabel(card),count:0};current.count+=1;grouped.set(key,current)});return [...grouped.values()].sort((left,right)=>left.label.localeCompare(right.label))};
if(!Array.isArray(saved?.selectedObjectives)){state.selectedObjectives=legacyObjective?[legacyObjective]:objectives().map(item=>item.key)}
const visible=()=>{const query=state.query.toLocaleLowerCase();const selected=new Set(state.selectedObjectives);const base=state.shuffle.length?state.shuffle:payload.cards.map((_,index)=>index);return base.filter(index=>{const card=payload.cards[index];return(!query||`${card.prompt} ${card.answer} ${objectiveLabel(card)}`.toLocaleLowerCase().includes(query))&&selected.has(card.learning_objective)&&(!state.cardType||card.card_type===state.cardType)&&(!state.difficulty||card.difficulty===state.difficulty)})};
const renderObjectives=()=>{const items=objectives();const selected=new Set(state.selectedObjectives);byId("objective-count").textContent=`${selected.size} of ${items.length} selected`;byId("objective-options").replaceChildren(...items.map(item=>{const label=document.createElement("label");label.className="objective-option";const input=document.createElement("input");input.type="checkbox";input.checked=selected.has(item.key);input.addEventListener("change",()=>{const next=new Set(state.selectedObjectives);input.checked?next.add(item.key):next.delete(item.key);state.selectedObjectives=[...next];state.index=0;state.revealed=false;render()});const text=document.createElement("span");text.textContent=item.label;const count=document.createElement("small");count.textContent=String(item.count);label.append(input,text,count);return label}))};
const renderCardList=indexes=>{byId("visible-card-count").textContent=`${indexes.length} cards`;byId("card-list").replaceChildren(...indexes.map((cardIndex,position)=>{const card=payload.cards[cardIndex];const button=document.createElement("button");button.type="button";button.className="card-list-item";button.setAttribute("aria-label",`Open card ${position+1}: ${card.prompt}`);if(position===state.index){button.setAttribute("aria-current","true")}const number=document.createElement("span");number.textContent=String(position+1);const text=document.createElement("span");const title=document.createElement("strong");title.textContent=card.prompt;const meta=document.createElement("small");meta.textContent=objectiveLabel(card);text.append(title,meta);button.append(number,text);button.addEventListener("click",()=>{state.index=position;state.revealed=false;render();byId("card").focus()});return button}))};
const render=()=>{const indexes=visible();renderObjectives();if(indexes.length)state.index=Math.max(0,Math.min(state.index,indexes.length-1));renderCardList(indexes);if(!indexes.length){byId("concept").textContent="";byId("prompt").textContent="No cards match these filters.";byId("answer").hidden=true;byId("position").textContent="0 / 0";byId("mastery").textContent=`${Object.keys(state.ratings).length} rated`;save();return}const card=payload.cards[indexes[state.index]];byId("concept").textContent=objectiveLabel(card);byId("prompt").textContent=card.prompt;byId("answer-text").textContent=card.answer;byId("source").textContent=card.source_reference;byId("answer").hidden=!state.revealed;document.querySelector("[data-action=flip]").textContent=state.revealed?"Hide answer":"Show answer";byId("position").textContent=`${state.index+1} / ${indexes.length}`;byId("mastery").textContent=`${Object.keys(state.ratings).length} rated`;const list=byId("card-list");const current=list.querySelector('[aria-current="true"]');if(current){const listBox=list.getBoundingClientRect();const itemBox=current.getBoundingClientRect();if(itemBox.top<listBox.top)list.scrollTop-=listBox.top-itemBox.top;else if(itemBox.bottom>listBox.bottom)list.scrollTop+=itemBox.bottom-listBox.bottom}save()};
const move=delta=>{state.index+=delta;state.revealed=false;render()};const download=(name,value)=>{const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:"application/json"}));link.download=name;link.click();URL.revokeObjectURL(link.href)};
document.querySelectorAll("[data-action]").forEach(button=>button.addEventListener("click",()=>{const action=button.dataset.action;if(action==="previous")move(-1);if(action==="next")move(1);if(action==="flip"){state.revealed=!state.revealed;render()}if(action==="shuffle"){state.shuffle=payload.cards.map((_,i)=>i).sort(()=>Math.random()-.5);state.index=0;render()}if(action==="select-all-objectives"){state.selectedObjectives=objectives().map(item=>item.key);state.index=0;render()}if(action==="clear-objectives"){state.selectedObjectives=[];state.index=0;render()}if(action==="fullscreen")document.documentElement.requestFullscreen?.();if(action==="export")download("flashcard-progress.json",state);if(action==="import")byId("import-progress").click();if(action==="reset"&&confirm("Reset saved progress?")){localStorage.removeItem(storageKey);location.reload()}}));
document.querySelectorAll("[data-rating]").forEach(button=>button.addEventListener("click",()=>{const indexes=visible();if(!indexes.length)return;const card=payload.cards[indexes[state.index]];state.ratings[card.card_id]=button.dataset.rating;move(1)}));byId("search").addEventListener("input",event=>{state.query=event.target.value;state.index=0;render()});byId("type-filter").addEventListener("change",event=>{state.cardType=event.target.value;state.index=0;render()});byId("difficulty-filter").addEventListener("change",event=>{state.difficulty=event.target.value;state.index=0;render()});
byId("import-progress").addEventListener("change",async event=>{const file=event.target.files[0];if(!file)return;state=JSON.parse(await file.text());render()});document.addEventListener("keydown",event=>{if(document.activeElement instanceof Element&&document.activeElement.closest("input,select,textarea,button,label"))return;if(event.key==="ArrowLeft")move(-1);if(event.key==="ArrowRight")move(1);if(event.key===" "){event.preventDefault();state.revealed=!state.revealed;render()}});populate();render();
"""
        return self._shell(deck.title, deck, body, script)

    def render_mock_exam(self, document: MockExamFileInput) -> str:
        body = """
<header><div><p class="eyebrow">Offline mock exam</p><h1 id="exam-title"></h1></div><div class="progress"><strong id="timer"></strong><span id="exam-progress"></span></div></header>
<section id="instructions" class="panel"><h2>Instructions</h2><p>Choose one answer per question. Progress saves automatically on this device.</p><label class="practice-toggle"><input id="practice-mode" type="checkbox"> Practice mode</label><button id="start" class="primary" type="button">Start exam</button></section>
<section id="exam-workspace" hidden><nav id="question-nav" aria-label="Question navigation"></nav><main class="exam-main"><article class="question-panel"><p class="eyebrow" id="question-meta"></p><h2 id="question-prompt"></h2><fieldset id="choices"></fieldset><section id="explanation" class="explanation" hidden><h3>Explanation</h3><p id="explanation-text"></p><p id="exam-source"></p></section></article><aside><button id="flag" type="button">Flag</button><button id="clear" type="button">Clear answer</button><button id="previous" type="button">Previous</button><button id="next" type="button">Next</button><button id="submit" class="primary" type="button">Submit exam</button></aside></main></section>
<section id="results" class="panel" hidden><h2>Results</h2><strong id="score"></strong><div id="breakdown"></div><button id="save-completed" class="primary" type="button">Save completed exam</button><button id="new-attempt" type="button">New attempt</button><button id="export-attempt" type="button">Export attempt JSON</button><button id="print" type="button">Print</button><h3>Attempt history</h3><ol id="history"></ol></section>
"""
        script = """
const payload=JSON.parse(document.getElementById("study-data").textContent);const exam=payload.exam;const storageKey=`exam-prep:${payload.package_id}:${payload.file_id}:v${payload.version}`;const importedAttemptElement=document.getElementById("attempt-data");const importedAttempt=importedAttemptElement?JSON.parse(importedAttemptElement.textContent):null;const initial={index:0,answers:{},flags:{},started:false,startedAt:null,completedAt:null,attemptId:null,timerStartedAt:null,remainingSeconds:exam.timer_minutes*60,submitted:false,practice:false,attempts:[]};const restored=importedAttempt?{answers:importedAttempt.answers,flags:importedAttempt.flags,started:true,startedAt:importedAttempt.started_at,completedAt:importedAttempt.completed_at,attemptId:importedAttempt.attempt_id,remainingSeconds:importedAttempt.remaining_seconds,submitted:true,attempts:[{attemptId:importedAttempt.attempt_id,completedAt:importedAttempt.completed_at,answers:importedAttempt.answers,flags:importedAttempt.flags,remainingSeconds:importedAttempt.remaining_seconds}]}:JSON.parse(localStorage.getItem(storageKey)||"null");let state={...initial,...restored};
const byId=id=>document.getElementById(id);const save=()=>localStorage.setItem(storageKey,JSON.stringify(state));const question=()=>exam.questions[state.index];const downloadJson=value=>{const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:"application/json"}));link.download="mock-exam-attempt.json";link.click();URL.revokeObjectURL(link.href)};const createAttemptId=()=>crypto.randomUUID?.()||`attempt-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const attemptPayload=()=>({schema_version:"1",attempt_id:state.attemptId,package_id:payload.package_id,package_version:payload.version,file_id:payload.file_id,exam_id:exam.exam_id,content_sha256:payload.content_sha256,started_at:typeof state.startedAt==="number"?new Date(state.startedAt).toISOString():state.startedAt,completed_at:state.completedAt,remaining_seconds:state.remainingSeconds,answers:state.answers,flags:state.flags});
const saveCompletedExam=()=>{if(!state.submitted)return;const clone=document.documentElement.cloneNode(true);clone.querySelector("#attempt-data")?.remove();const attemptData=document.createElement("script");attemptData.type="application/json";attemptData.id="attempt-data";attemptData.textContent=JSON.stringify(attemptPayload()).replaceAll("<","\\u003c");const scripts=clone.querySelectorAll("script");const runtime=scripts[scripts.length-1];runtime.parentNode.insertBefore(attemptData,runtime);const completed=`<!doctype html>\n${clone.outerHTML}`;const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([completed],{type:"text/html"}));link.download=`${exam.title.replace(/[^a-z0-9]+/gi,"-").replace(/^-|-$/g,"")}-completed.html`;link.click();URL.revokeObjectURL(link.href)};
const renderNav=()=>{byId("question-nav").replaceChildren(...exam.questions.map((item,index)=>{const button=document.createElement("button");button.type="button";button.textContent=String(item.question_number);const states=[];if(index===state.index){states.push("current");button.setAttribute("aria-current","true")}if(state.answers[item.question_id]!==undefined)states.push("answered");if(state.flags[item.question_id])states.push("flagged");button.className=states.join(" ");button.setAttribute("aria-label",`Question ${item.question_number}${states.length?`, ${states.join(", ")}`:""}`);button.addEventListener("click",()=>{state.index=index;render()});return button}))};
const renderTimer=()=>{const remaining=Math.max(0,state.remainingSeconds);byId("timer").textContent=`${String(Math.floor(remaining/60)).padStart(2,"0")}:${String(remaining%60).padStart(2,"0")}`};
const renderQuestion=()=>{const item=question();byId("question-meta").textContent=`Question ${item.question_number} · ${item.domain} · ${item.subtopic} · ${item.question_type} · ${item.difficulty}`;byId("question-prompt").textContent=item.prompt;const fields=item.choices.map((choice,index)=>{const label=document.createElement("label");const input=document.createElement("input");input.type="radio";input.name="choice";input.value=String(index);input.checked=state.answers[item.question_id]===index;input.disabled=state.submitted;input.addEventListener("change",()=>{state.answers[item.question_id]=index;save();byId("exam-progress").textContent=`${Object.keys(state.answers).length} / ${exam.questions.length} answered`;renderNav()});const span=document.createElement("span");span.textContent=`${String.fromCharCode(65+index)}. ${choice}`;label.append(input,span);if(state.submitted){const correctAnswerId=item.correct_choice_index;if(index===correctAnswerId)label.classList.add("correct");if(input.checked&&index!==correctAnswerId)label.classList.add("incorrect")}return label});byId("choices").replaceChildren(...fields);byId("explanation").hidden=!state.submitted;byId("explanation-text").textContent=item.explanation;byId("exam-source").textContent=item.source_reference;byId("flag").textContent=state.flags[item.question_id]?"Unflag":"Flag";byId("exam-progress").textContent=`${Object.keys(state.answers).length} / ${exam.questions.length} answered`;renderNav();renderTimer();save()};
const buildBreakdown=(label,pick)=>{const section=document.createElement("section");const sectionTitle=document.createElement("h3");sectionTitle.textContent=label;section.append(sectionTitle);const list=document.createElement("dl");const groups={};exam.questions.forEach(item=>{const name=pick(item);groups[name]??={correct:0,total:0};groups[name].total+=1;if(state.answers[item.question_id]===item.correct_choice_index)groups[name].correct+=1});Object.entries(groups).sort(([left],[right])=>left.localeCompare(right)).forEach(([name,value])=>{const row=document.createElement("div");const term=document.createElement("dt");term.textContent=name;const data=document.createElement("dd");data.textContent=`${value.correct} / ${value.total}`;row.append(term,data);list.append(row)});section.append(list);return section};
const renderResults=()=>{if(!state.submitted){byId("results").hidden=true;return}const correct=exam.questions.filter(item=>state.answers[item.question_id]===item.correct_choice_index);byId("score").textContent=`${correct.length} / ${exam.questions.length} (${Math.round(correct.length/exam.questions.length*100)}%)`;const total=buildBreakdown("Total",()=>"All questions");total.querySelector("h3").textContent="Total score";byId("breakdown").replaceChildren(total,buildBreakdown("Domain",item=>item.domain),buildBreakdown("Subtopic",item=>item.subtopic),buildBreakdown("Question type",item=>item.question_type),buildBreakdown("Difficulty",item=>item.difficulty));byId("history").replaceChildren(...state.attempts.map(attempt=>{const row=document.createElement("li");row.textContent=`${attempt.completedAt}: ${attempt.correct} / ${exam.questions.length}`;return row}));byId("results").hidden=false};
const submitAttempt=()=>{state.submitted=true;state.attemptId=state.attemptId||createAttemptId();state.completedAt=state.completedAt||new Date().toISOString();const correct=exam.questions.filter(item=>state.answers[item.question_id]===item.correct_choice_index).length;state.attempts.push({attemptId:state.attemptId,completedAt:state.completedAt,correct,answers:{...state.answers},flags:{...state.flags},remainingSeconds:state.remainingSeconds});render()};
const render=()=>{byId("exam-title").textContent=exam.title;byId("instructions").hidden=state.started;byId("exam-workspace").hidden=!state.started;byId("practice-mode").checked=state.practice;if(state.started)renderQuestion();else renderTimer();renderResults()};const move=delta=>{state.index=Math.max(0,Math.min(exam.questions.length-1,state.index+delta));render()};
byId("start").addEventListener("click",()=>{state.started=true;state.startedAt=state.startedAt||Date.now();state.timerStartedAt=Date.now();state.practice=byId("practice-mode").checked;save();render()});byId("previous").addEventListener("click",()=>move(-1));byId("next").addEventListener("click",()=>move(1));byId("flag").addEventListener("click",()=>{const id=question().question_id;state.flags[id]=!state.flags[id];render()});byId("clear").addEventListener("click",()=>{delete state.answers[question().question_id];render()});
byId("submit").addEventListener("click",()=>{if(!confirm(`Submit with ${exam.questions.length-Object.keys(state.answers).length} unanswered question(s)?`))return;submitAttempt()});byId("save-completed").addEventListener("click",saveCompletedExam);byId("new-attempt").addEventListener("click",()=>{localStorage.removeItem(storageKey);state={...initial};render()});byId("export-attempt").addEventListener("click",()=>downloadJson(attemptPayload()));byId("print").addEventListener("click",()=>print());
setInterval(()=>{if(!state.started||state.submitted||!state.timerStartedAt)return;const elapsed=Math.floor((Date.now()-state.timerStartedAt)/1000);if(elapsed<=0)return;state.remainingSeconds=Math.max(0,state.remainingSeconds-elapsed);state.timerStartedAt=Date.now();save();renderTimer();if(state.remainingSeconds===0)submitAttempt()},1000);render();
"""
        return self._shell(document.exam.title, document, body, script)

    def render_formula_review(self, document: FormulaFileInput) -> str:
        body = """
<header><div><p class="eyebrow">Formula review</p><h1 id="formula-title"></h1></div><label>Search<input id="formula-search" type="search"></label></header><main id="formula-list" class="formula-grid"></main>
"""
        script = """
const payload=JSON.parse(document.getElementById("study-data").textContent);const storageKey=`exam-prep:${payload.package_id}:${payload.file_id}:v${payload.version}`;const state=JSON.parse(localStorage.getItem(storageKey)||"{}");const list=document.getElementById("formula-list");document.getElementById("formula-title").textContent=payload.title;const render=()=>{const query=document.getElementById("formula-search").value.toLocaleLowerCase();list.replaceChildren(...payload.formulas.filter(item=>`${item.name} ${item.expression}`.toLocaleLowerCase().includes(query)).map(item=>{const card=document.createElement("article");card.className="panel";const name=document.createElement("h2");name.textContent=item.name;const expression=document.createElement("code");expression.textContent=item.expression;const details=document.createElement("details");details.open=Boolean(state[item.formula_id]);details.addEventListener("toggle",()=>{state[item.formula_id]=details.open;localStorage.setItem(storageKey,JSON.stringify(state))});const summary=document.createElement("summary");summary.textContent="Application and source";const application=document.createElement("p");application.textContent=item.application;const source=document.createElement("p");source.textContent=item.source_reference;details.append(summary,application,source);card.append(name,expression,details);return card}))};document.getElementById("formula-search").addEventListener("input",render);render();
"""
        return self._shell(document.title, document, body, script)

    def render_blueprint(self, document: BlueprintFileInput) -> str:
        return self._render_structured_report(document.title, document, "Exam blueprint")

    def render_validation(self, document: ValidationFileInput) -> str:
        return self._render_structured_report(document.title, document, "Validation report")

    def _render_structured_report(
        self,
        title: str,
        document: BlueprintFileInput | ValidationFileInput,
        label: str,
    ) -> str:
        body = """
<header><div><p class="eyebrow" id="report-label"></p><h1 id="report-title"></h1></div><button id="report-print" type="button">Print</button></header><main id="report-content" class="report"></main>
"""
        script = f"""
const payload=JSON.parse(document.getElementById("study-data").textContent);document.getElementById("report-label").textContent={json.dumps(label)};document.getElementById("report-title").textContent=payload.title;const root=document.getElementById("report-content");const render=(value,name)=>{{const section=document.createElement("section");section.className="panel";const heading=document.createElement("h2");heading.textContent=name;section.append(heading);const pre=document.createElement("pre");pre.textContent=JSON.stringify(value,null,2);section.append(pre);return section}};Object.entries(payload).filter(([key])=>!["package_id","file_id","version","title"].includes(key)).forEach(([key,value])=>root.append(render(value,key.replaceAll("_"," "))));document.getElementById("report-print").addEventListener("click",()=>print());
"""
        return self._shell(title, document, body, script)

    @staticmethod
    def _shell(title: str, data: BaseModel, body: str, script: str) -> str:
        css = """
:root{color-scheme:light;--artifact-ink:#17202a;--artifact-muted:#637083;--artifact-line:#dce3e1;--artifact-paper:#fff;--artifact-wash:#f3f7f5;--artifact-accent:#087f6d;--artifact-accent-dark:#075d52;--artifact-warn:#a35b00;--artifact-success-bg:#e8f7f2;--artifact-danger:#b93737;--artifact-danger-bg:#fff0f0;--space-1:4px;--space-2:8px;--space-3:12px;--space-4:16px;--space-5:20px;--space-6:24px;--radius-sm:6px;--radius-md:8px;--shadow-panel:0 8px 32px rgba(23,32,42,.06);font-family:"Avenir Next","SF Pro Display","Helvetica Neue",Arial,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--artifact-wash);color:var(--artifact-ink);min-height:100vh}body>header,body>main,body>section,body>footer{width:min(1120px,calc(100% - 32px));margin-inline:auto}header{display:flex;justify-content:space-between;align-items:center;gap:var(--space-6);padding:28px 0 var(--space-5)}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(1.65rem,4vw,2.55rem)}button,.button,input,select{font:inherit}button,.button{min-height:44px;border:1px solid var(--artifact-line);border-radius:var(--radius-sm);background:var(--artifact-paper);padding:10px var(--space-4);color:var(--artifact-ink);cursor:pointer}button:hover,button:focus-visible,.button:hover{border-color:var(--artifact-accent);outline:3px solid color-mix(in srgb,var(--artifact-accent) 18%,transparent)}button.primary{background:var(--artifact-accent);color:white;border-color:var(--artifact-accent)}button.primary:hover{background:var(--artifact-accent-dark)}input,select{min-height:44px;border:1px solid var(--artifact-line);border-radius:var(--radius-sm);padding:9px var(--space-3);background:white}label{display:grid;gap:5px;color:var(--artifact-muted)}.eyebrow{text-transform:uppercase;color:var(--artifact-accent-dark);font-size:.78rem;font-weight:750;letter-spacing:0}.toolbar,footer,.ratings{display:flex;align-items:end;gap:var(--space-3);flex-wrap:wrap}.toolbar{display:grid;grid-template-columns:minmax(150px,1fr) minmax(240px,2fr) minmax(150px,1fr) minmax(110px,.7fr) auto auto;padding:14px 0}.toolbar input,.toolbar select{width:100%}.study-card,.panel,.question-panel{background:var(--artifact-paper);border:1px solid var(--artifact-line);border-radius:var(--radius-md);padding:clamp(24px,5vw,56px);box-shadow:var(--shadow-panel)}body>main{display:grid;grid-template-columns:52px minmax(0,1fr) 52px;align-items:center;gap:18px;min-height:56vh}.study-card{text-align:center;min-height:420px;display:flex;flex-direction:column;justify-content:center;align-items:center}.study-card h2{font-size:clamp(1.6rem,4vw,3.35rem);max-width:900px}.flip{margin-top:28px}.side-nav{min-width:44px;min-height:44px;background:transparent;border:0;font-size:2rem}.ratings{justify-content:center;padding:var(--space-5) 0}.ratings button{min-width:100px}footer{justify-content:center;padding:var(--space-2) 0 var(--space-8,32px)}.rule{height:1px;background:var(--artifact-line);margin:28px 0}.progress{text-align:right;display:grid;gap:6px}.exam-main{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:18px}.exam-main aside{display:grid;align-content:start;gap:10px}.exam-main fieldset{border:0;padding:0;display:grid;gap:10px}.exam-main fieldset label{grid-template-columns:24px 1fr;align-items:center;color:var(--artifact-ink);border:1px solid var(--artifact-line);border-radius:var(--radius-sm);padding:14px}.exam-main label.correct{border-color:var(--artifact-accent);background:var(--artifact-success-bg)}.exam-main label.incorrect{border-color:var(--artifact-danger);background:var(--artifact-danger-bg)}#question-nav{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:var(--space-4)}#question-nav button{width:44px;padding:0}#question-nav .answered{border-color:var(--artifact-accent)}#question-nav .flagged{box-shadow:inset 0 -4px var(--artifact-warn)}#question-nav .current{background:var(--artifact-ink);color:white}.explanation{margin-top:var(--space-6);border-top:1px solid var(--artifact-line);padding-top:var(--space-5)}.formula-grid,.report{display:grid;gap:var(--space-4);padding-bottom:var(--space-8,32px)}.formula-grid{grid-template-columns:repeat(auto-fit,minmax(280px,1fr))}.formula-grid code{display:block;font-size:1.12rem;white-space:pre-wrap;margin:18px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere}.panel{margin-bottom:18px}#breakdown{display:grid;gap:14px;margin-top:18px}#breakdown section{border:1px solid var(--artifact-line);border-radius:var(--radius-md);padding:14px}#breakdown dl{display:grid;gap:var(--space-2);margin:0}#breakdown div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:var(--space-3)}#breakdown dt{overflow-wrap:anywhere;color:var(--artifact-muted)}#breakdown dd{margin:0;font-weight:800}@media(max-width:720px){header{align-items:flex-start;flex-direction:column}body>main{grid-template-columns:44px minmax(0,1fr) 44px;gap:var(--space-1)}.study-card{min-height:480px;padding:22px}.exam-main{grid-template-columns:1fr}.exam-main aside{grid-template-columns:repeat(2,1fr)}#submit{grid-column:1/-1}.toolbar{grid-template-columns:1fr}.toolbar label{width:100%}.toolbar input,.toolbar select{width:100%}}@media print{button,.toolbar,footer,#question-nav{display:none!important}body{background:white}.panel,.question-panel,.study-card{box-shadow:none}}
"""
        css += """
#question-nav{flex-wrap:nowrap;overflow-x:auto;padding-bottom:8px}#question-nav button{flex:0 0 44px}.practice-toggle{display:flex;align-items:center;gap:8px;width:fit-content;margin:24px 0 8px}.practice-toggle input{width:18px;height:18px;min-height:0;margin:0;padding:0}
.flashcard-workspace{display:grid;grid-template-columns:minmax(240px,300px) minmax(0,1fr);align-items:start;gap:18px;min-height:56vh}.deck-browser{position:sticky;top:12px;max-height:calc(100vh - 24px);display:flex;flex-direction:column;background:var(--artifact-paper);border:1px solid var(--artifact-line);border-radius:var(--radius-md);box-shadow:var(--shadow-panel);overflow:hidden}.browser-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;padding:16px;border-bottom:1px solid var(--artifact-line)}.browser-heading .eyebrow{margin-bottom:4px}.compact-actions{display:flex;gap:6px}.compact-actions button{min-height:36px;padding:6px 9px;font-size:.82rem}.objective-options{display:grid;gap:2px;max-height:30vh;overflow:auto;padding:8px}.objective-option{display:grid;grid-template-columns:20px minmax(0,1fr) auto;align-items:start;gap:8px;padding:9px;border-radius:var(--radius-sm);color:var(--artifact-ink);cursor:pointer}.objective-option:hover{background:var(--artifact-wash)}.objective-option input{min-height:18px;width:18px;margin:1px 0 0;padding:0}.objective-option small{color:var(--artifact-muted)}.card-list-heading{border-top:1px solid var(--artifact-line)}.card-list{display:grid;gap:4px;overflow:auto;padding:8px}.card-list-item{width:100%;display:grid;grid-template-columns:28px minmax(0,1fr);align-items:start;gap:8px;text-align:left;padding:9px;border-color:transparent}.card-list-item>span:first-child{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:var(--artifact-wash);font-size:.75rem}.card-list-item>span:last-child{display:grid;gap:3px;min-width:0}.card-list-item strong{font-size:.86rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-list-item small{font-size:.72rem;color:var(--artifact-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-list-item[aria-current="true"]{border-color:var(--artifact-accent);background:var(--artifact-success-bg)}.deck-column{min-width:0}.deck-stage{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;align-items:center;gap:12px}.deck-stage .study-card{min-height:500px}.deck-column .ratings{padding-bottom:0}
@media(max-width:900px){.flashcard-workspace{grid-template-columns:1fr}.deck-browser{position:static;max-height:none}.objective-options{max-height:220px}.card-list{max-height:240px}.deck-stage{grid-template-columns:44px minmax(0,1fr) 44px}}
@media(max-width:720px){.progress{text-align:left}.toolbar{grid-template-columns:repeat(2,minmax(0,1fr));align-items:end}.toolbar label:first-child{grid-column:1/-1}.flashcard-workspace{width:min(100% - 20px,1120px)}.deck-column{order:-1}.deck-stage{grid-template-columns:44px minmax(0,1fr) 44px;gap:2px}.deck-stage .study-card{min-height:460px;padding:22px}.compact-actions{flex-direction:column}.ratings button{min-width:calc(50% - 8px);flex:1}}
"""
        return (
            "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
            f"<title>{html.escape(title)}</title>"
            '<link rel="icon" type="image/png" href="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=">'
            f"<style>{css}</style></head><body>{body}"
            f'<script type="application/json" id="study-data">{_json_for_script(data)}</script>'
            f"<script>{script}</script></body></html>"
        )


def _json_for_script(value: BaseModel | dict[str, object]) -> str:
    payload = value.model_dump(mode="json") if isinstance(value, BaseModel) else value
    raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    return raw.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
